package com.sakti.banking.service; import com.sakti.banking.dto.BeneficiaryRequest; import com.sakti.banking.entity.*; import com.sakti.banking.exception.BusinessException; import com.sakti.banking.repository.BeneficiaryRepository; import org.springframework.stereotype.Service; import java.util.*; @Service public class BeneficiaryService {private final BeneficiaryRepository repo;private final UserService users;private final AuditService audit;public BeneficiaryService(BeneficiaryRepository r,UserService u,AuditService a){repo=r;users=u;audit=a;} public Beneficiary add(String email,BeneficiaryRequest r){AppUser u=users.requireByEmail(email);if(repo.existsByOwnerIdAndAccountNumber(u.getId(),r.accountNumber()))throw new BusinessException("Beneficiary already exists");Beneficiary b=new Beneficiary();b.setOwner(u);b.setName(r.name());b.setAccountNumber(r.accountNumber());b.setBankCode(r.bankCode());audit.record(email,"BENEFICIARY_ADD",r.accountNumber(),"SUCCESS");return repo.save(b);} public List<Beneficiary> mine(String email){return repo.findByOwnerEmailIgnoreCaseOrderByCreatedAtDesc(email);} }
